<script setup lang="ts">import{ref,onMounted,watch}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit,isAdmin}from '../stores/auth';import*as notes from '../api/notes';import{download}from '../api/client';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';const route=useRoute(),run=ref(Number(route.query.run)||0),sensitivity=ref(Number(route.query.sensitivity)||0),title=ref('预设湿度层独立复验说明'),interpretation=ref('核对总体与分层成功率方向，以及固定边际条件双侧证据；若附敏感性复核，同时核对少量误判下共同OR方向与精确p的变化范围。不将共同OR或p值解释为封装因果效果。'),action=ref('保持预设湿度层，补充独立试片并记录封装批次、浸湿条件和原始四格；对稀疏层复核成功/失败判读。'),comment=ref('层边际、精确双侧定义与固定边际修正范围已核对，按预设方案开展独立复验。'),notice=ref(''),{error,execute}=useTask();onMounted(()=>execute(async()=>{await load();run.value=run.value||lab.runs.find(r=>r.status==='completed')?.id||0}));watch(run,()=>{if(!lab.sensitivities.some(s=>s.id===sensitivity.value&&s.base_run_id===run.value))sensitivity.value=0});
function create(){execute(async()=>{await notes.create({title:title.value,run_id:run.value,sensitivity_run_id:sensitivity.value||null,interpretation:interpretation.value,action:action.value});notice.value='复验说明已建立，等待负责人审阅';await load()})}function review(id:number,decision:string){execute(async()=>{await notes.review(id,decision,comment.value);await load();notice.value='审阅状态已保存'})}function exportNote(id:number){execute(()=>download('/notes/'+id+'/export','cenan-observation-'+id+'.csv'))}</script><template><PageHeading index="05" title="让分层证据，落到独立复验。" text="研究员起草，负责人审阅，阅读者只下载已批准说明。导出附原研究指纹、可选敏感性冻结结果与方法边界。"/><ErrorNotice :message="error" @retry="execute(load)"/><p v-if="notice" class="success" role="status">{{notice}}</p><div class="notes-layout"><form v-if="canEdit" @submit.prevent="create"><p class="eyebrow">NEW VERIFICATION NOTE</p><label>关联研究<select v-model.number="run" aria-label="关联研究"><option v-for="r in lab.runs.filter(r=>r.status==='completed')" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>附敏感性复核（可选）<select v-model.number="sensitivity" aria-label="附敏感性复核"><option :value="0">不附加</option><option v-for="s in lab.sensitivities.filter(s=>s.base_run_id===run&&s.status==='completed')" :value="s.id">#{{s.id}} {{s.name}}</option></select></label><label>说明名称<input v-model="title" required minlength="3"></label><label>复验解释<textarea v-model="interpretation" rows="5" required minlength="8"/></label><label>复验动作<textarea v-model="action" rows="4" required minlength="5"/></label><button class="primary" :disabled="!run">保存复验说明 →</button></form><section><div class="section-title"><h2>复验档案</h2><span>{{lab.notes.length}}份</span></div><label v-if="isAdmin">审阅意见<textarea v-model="comment" rows="2"/></label><article v-for="n in lab.notes" class="observation-note"><div><p class="eyebrow">NOTE {{n.id}} / RUN {{n.run_id}}<template v-if="n.sensitivity_run_id"> / SENSITIVITY {{n.sensitivity_run_id}}</template></p><StatusBadge :status="n.status"/></div><h2>{{n.title}}</h2><p>{{n.interpretation}}</p><p class="action-note">{{n.action}}</p><p v-if="n.review_comment" class="review-comment">{{n.approved_by}} · {{n.review_comment}}</p><div class="actions"><button v-if="isAdmin&&n.status==='draft'" class="primary" @click="review(n.id,'approved')">批准说明</button><button v-if="isAdmin&&n.status==='draft'" class="outline" @click="review(n.id,'rejected')">退回</button><button v-if="n.status==='approved'" class="outline" @click="exportNote(n.id)">下载获批CSV ↗</button></div></article></section></div></template>
